/** Explicit display metadata; the existing AdminService remains the authority for writes. */
@Service @Transactional(readOnly=true)
public class AdminPresentation {
    private final Store db;private final AdminService admin;private final Clock clock;
    public AdminPresentation(Store db,AdminService admin,Clock clock){this.db=db;this.admin=admin;this.clock=clock;}
    private static final Map<String,String> LABELS=Map.ofEntries(
        Map.entry("genres","Thể loại"),Map.entry("title","Tiêu đề"),Map.entry("name","Tên"),Map.entry("slug","Đường dẫn"),Map.entry("description","Mô tả"),Map.entry("poster","Poster"),Map.entry("banner","Banner"),Map.entry("trailer","Trailer"),Map.entry("image","Hình ảnh"),Map.entry("ageRating","Phân loại tuổi"),Map.entry("status","Trạng thái"),Map.entry("duration","Thời lượng (phút)"),Map.entry("releaseDate","Ngày khởi chiếu"),Map.entry("featured","Nổi bật"),Map.entry("active","Đang hoạt động"),Map.entry("biography","Tiểu sử"),Map.entry("movieId","Phim"),Map.entry("genreId","Thể loại"),Map.entry("personId","Diễn viên / Đạo diễn"),Map.entry("kind","Loại"),Map.entry("city","Tỉnh / Thành phố"),Map.entry("address","Địa chỉ"),Map.entry("phone","Điện thoại"),Map.entry("cinemaId","Rạp"),Map.entry("roomId","Phòng"),Map.entry("format","Định dạng"),Map.entry("label","Tên ghế"),Map.entry("rowLabel","Hàng ghế"),Map.entry("position","Vị trí cột"),Map.entry("type","Loại ghế"),Map.entry("coupleGroup","Nhóm ghế đôi"),Map.entry("startsAt","Bắt đầu (giờ Việt Nam)"),Map.entry("endsAt","Kết thúc (giờ Việt Nam)"),Map.entry("language","Ngôn ngữ"),Map.entry("surcharge","Phụ thu (VND)"),Map.entry("seatType","Loại ghế"),Map.entry("dayType","Loại ngày"),Map.entry("fromMinute","Giờ bắt đầu"),Map.entry("toMinute","Giờ kết thúc"),Map.entry("amount","Giá mỗi ghế vật lý (VND)"),Map.entry("price","Giá (VND)"),Map.entry("code","Mã"),Map.entry("value","Mức giảm (% hoặc VND theo loại)"),Map.entry("minimum","Đơn tối thiểu (VND)"),Map.entry("maximum","Giảm tối đa (VND; 0 = không giới hạn)"),Map.entry("quota","Tổng lượt"),Map.entry("perUser","Lượt / khách"),Map.entry("link","Liên kết nội bộ"),Map.entry("body","Nội dung"),Map.entry("publishedAt","Ngày xuất bản"),Map.entry("email","Email"),Map.entry("role","Vai trò"),Map.entry("enabled","Tài khoản hoạt động"),Map.entry("visible","Hiển thị bình luận"),Map.entry("userId","Khách hàng"),Map.entry("stars","Điểm"),Map.entry("comment","Bình luận"),Map.entry("capacity","Ghế hoạt động")
    );
    private static final Map<String,String> TEXT=Map.ofEntries(Map.entry("PAID","Đã thanh toán"),Map.entry("PENDING_PAYMENT","Chờ thanh toán"),Map.entry("EXPIRED","Hết hạn"),Map.entry("CANCELLED","Đã hủy"),Map.entry("SUCCEEDED","Thành công"),Map.entry("FAILED","Thất bại"),Map.entry("CREATED","Mới tạo"),Map.entry("PENDING","Đang xác minh"),Map.entry("VALID","Chưa vào"),Map.entry("USED","Đã vào"),Map.entry("VOID","Vô hiệu"),Map.entry("OPEN","Mở bán"),Map.entry("DRAFT","Nháp"),Map.entry("COMING_SOON","Sắp chiếu"),Map.entry("NOW_SHOWING","Đang chiếu"),Map.entry("STOPPED","Ngừng chiếu"),Map.entry("STANDARD","Thường"),Map.entry("VIP","VIP"),Map.entry("COUPLE","Ghế đôi"),Map.entry("WEEKDAY","Thứ 2–6"),Map.entry("WEEKEND","Thứ 7, Chủ nhật"),Map.entry("CUSTOMER","Khách hàng"),Map.entry("STAFF","Nhân viên"),Map.entry("ADMIN","Quản trị viên"),Map.entry("ACTOR","Diễn viên"),Map.entry("DIRECTOR","Đạo diễn"),Map.entry("FOOD","Đồ ăn"),Map.entry("DRINK","Đồ uống"),Map.entry("COMBO","Combo"),Map.entry("FIXED","Số tiền cố định"),Map.entry("PERCENT","Phần trăm"),Map.entry("BANNER","Banner"),Map.entry("ARTICLE","Bài viết"),Map.entry("OFFER","Ưu đãi"),Map.entry("POLICY","Chính sách"),Map.entry("ABOUT","Giới thiệu"),Map.entry("CONTACT","Liên hệ"),Map.entry("NOTICE","Thông báo"),Map.entry("RESERVED","Đang giữ"),Map.entry("RELEASED","Đã trả lượt"));
    public static String text(Object value){if(value==null)return "—";if(Set.of("STANDARD","VIP","COUPLE").contains(value.toString()))return RoomSetup.type(value.toString());return TEXT.getOrDefault(value.toString(),value.toString());}
    public static String label(String name){return LABELS.getOrDefault(name,name);}
    public record Column(String key,String label){public String getLabel(){return label;}}
    public List<Column> columns(String key){String fields=switch(key){case "movies"->"title,genres,status,releaseDate,duration,active";case "genres"->"name,active";case "people"->"name,biography,active";case "movie-genres"->"movieId,genreId";case "credits"->"movieId,personId,kind";case "cinemas"->"name,city,address,phone,active";case "rooms"->"name,format,capacity,active";case "seats"->"label,type,coupleGroup,active";case "showtimes"->"movieId,roomId,timeRange,status,surcharge";case "prices"->"seatType,dayType,timeRange,amount,pairAmount";case "products"->"name,kind,price,active";case "vouchers"->"code,kind,value,startsAt,endsAt,active";case "contents"->"title,kind,publishedAt,active";case "users"->"name,email,role,cinemaId,enabled";case "reviews"->"movieId,userId,stars,comment,visible";default->throw new IllegalArgumentException("Mục không tồn tại.");};return Arrays.stream(fields.split(",")).map(f->new Column(f,f.equals("timeRange")?"Khung giờ":f.equals("pairAmount")?"Giá cả cặp":label(f))).toList();}
    public Map<String,Object> list(String key,String q,String state,String activity,Long cinemaId,Long roomId,int page){return list(key,q,state,activity,cinemaId,roomId,null,null,"",page);}
    public Map<String,Object> list(String key,String q,String state,String activity,Long cinemaId,Long roomId,Long movieId,LocalDate day,String dayType,int page){
        var resource=admin.resource(key);Set<String> fields=Set.of(resource.fields().split(","));StringBuilder where=new StringBuilder(" where 1=1");Map<String,Object> params=new HashMap<>();
        String stateField=stateField(key);if(!state.isBlank()&&!stateField.isEmpty()){if(key.equals("movies")){where.append(" and ").append(MovieLifecycle.expression("e",":movieToday")).append("=:state");params.put("movieToday",MovieLifecycle.today(clock));}else where.append(" and e.").append(stateField).append("=:state");params.put("state",Set.of("active","enabled","visible").contains(stateField)?Boolean.valueOf(state):state);}
        String activeField=fields.contains("active")?"active":fields.contains("enabled")?"enabled":fields.contains("visible")?"visible":"";if(!activity.isBlank()&&!activeField.isEmpty()){where.append(" and e.").append(activeField).append("=:activity");params.put("activity",Boolean.valueOf(activity));}
        if(cinemaId!=null){if(key.equals("cinemas"))where.append(" and e.id=:cinema");else if(fields.contains("cinemaId"))where.append(" and e.cinemaId=:cinema");else if(fields.contains("roomId"))where.append(" and exists (select r.id from ").append(db.entityName(Room.class)).append(" r where r.id=e.roomId and r.cinemaId=:cinema)");else throw new IllegalArgumentException("Mục này không có bộ lọc rạp.");params.put("cinema",cinemaId);}
        if(roomId!=null&&fields.contains("roomId")){where.append(" and e.roomId=:room");params.put("room",roomId);}
        if(key.equals("seats")&&roomId==null)where.append(" and 1=0");
        if(cinemaId==null&&Set.of("rooms","seats","showtimes","prices").contains(key))where.append(" and 1=0");
        if(key.equals("showtimes")&&day!=null){where.append(" and e.startsAt>=:from and e.startsAt<:until");params.put("from",day.atStartOfDay(ReportService.ZONE).toInstant());params.put("until",day.plusDays(1).atStartOfDay(ReportService.ZONE).toInstant());if(movieId!=null){where.append(" and e.movieId=:movie");params.put("movie",movieId);}}
        if(key.equals("prices")&&!dayType.isBlank()){where.append(" and e.dayType=:dayType");params.put("dayType",dayType);}
        if(!q.isBlank()){List<String> terms=new ArrayList<>();for(Field f:resource.type().getFields()){if(f.getType()==String.class&&!Set.of("passwordHash","token","tokenHash","avatar","poster","banner","trailer","image").contains(f.getName()))terms.add("lower(e."+f.getName()+") like :q escape '!'");}
            for(var ref:referenceTypes().entrySet())if(fields.contains(ref.getKey())){String name=ref.getValue()==Movie.class?"title":"name";terms.add("exists (select x.id from "+db.entityName(ref.getValue())+" x where x.id=e."+ref.getKey()+" and lower(x."+name+") like :q escape '!')");}
            where.append(" and (").append(String.join(" or ",terms)).append(")");params.put("q","%"+q.toLowerCase(Locale.ROOT).replace("!","!!").replace("%","!%").replace("_","!_")+"%");}
        String from=" from "+db.entityName(resource.type())+" e"+where;var countQuery=db.entityManager().createQuery("select count(e)"+from,Long.class);String sort=key.equals("showtimes")?"e.movieId,e.startsAt,e.id":key.equals("seats")?"e.rowLabel,e.position,e.id":key.equals("prices")?"e.seatType,e.dayType,e.fromMinute,e.id":"e.id desc";var query=db.entityManager().createQuery("select e"+from+" order by "+sort,resource.type());params.forEach((n,v)->{query.setParameter(n,v);countQuery.setParameter(n,v);});long total=countQuery.getSingleResult();int current=AdminPage.number(page,total);List<? extends Row> records=query.setFirstResult(current*AdminPage.SIZE).setMaxResults(AdminPage.SIZE).getResultList();
        Map<String,Map<Long,String>> refs=references(records);Map<Long,Long> capacities=new HashMap<>();if(key.equals("rooms")&&!records.isEmpty())db.query("select s.roomId,count(s) from "+db.entityName(Seat.class)+" s where s.active=true and s.roomId in ?1 group by s.roomId",Object[].class,records.stream().map(r->r.id).toList()).forEach(row->capacities.put((Long)row[0],(Long)row[1]));
        Map<Long,List<String>> genreNames=new HashMap<>();if(key.equals("movies")&&!records.isEmpty())db.query("select x.movieId,g.name from "+db.entityName(MovieGenre.class)+" x, "+db.entityName(Genre.class)+" g where x.genreId=g.id and g.active=true and x.movieId in ?1 order by g.name",Object[].class,records.stream().map(r->r.id).toList()).forEach(row->genreNames.computeIfAbsent((Long)row[0],k->new ArrayList<>()).add((String)row[1]));Set<Long> usedMovies=new HashSet<>();if(key.equals("movies")&&!records.isEmpty()){var ids=records.stream().map(r->r.id).toList();for(Class<? extends Row> type:List.of(Showtime.class,Favorite.class,Review.class,Subscription.class))db.query("select distinct e.movieId from "+db.entityName(type)+" e where e.movieId in ?1",Long.class,ids).forEach(usedMovies::add);}List<Map<String,Object>> matches=new ArrayList<>();for(Row row:records){
            var raw=db.view(row);
            Map<String,Object> display=new LinkedHashMap<>();for(var e:raw.entrySet())display.put(e.getKey(),format(e.getKey(),e.getValue(),refs));display.put("capacity",capacities.getOrDefault(row.id,0L));if(key.equals("movies"))display.put("genres",genreNames.containsKey(row.id)?String.join(" · ",genreNames.get(row.id)):"Chưa phân loại");
            if(row instanceof Showtime show)display.put("timeRange",AdminReads.interval(show.startsAt,show.endsAt));
            if(row instanceof Price price){display.put("timeRange",time(price.fromMinute)+"–"+time(price.toMinute));display.put("pairAmount",price.seatType.equals("COUPLE")?db.money(Math.multiplyExact(price.amount,2)):"—");}
            List<Map<String,Object>> cells=new ArrayList<>();for(Column column:columns(key))cells.add(Map.of("label",column.label(),"value",Objects.toString(display.get(column.key()),"—"),"badge",Set.of("status","role","active","enabled","visible").contains(column.key()),"expandable",Set.of("biography","comment","address","title","name","movieId").contains(column.key())));
            String name=Objects.toString(raw.getOrDefault("title",raw.getOrDefault("name",raw.getOrDefault("code",raw.getOrDefault("label","#"+row.id)))));
            matches.add(Map.of("active",Boolean.TRUE.equals(raw.get("active")),"stopped","STOPPED".equals(raw.get("status")),"canDelete",!usedMovies.contains(row.id),"id",row.id,"email",Objects.toString(raw.get("email"),""),"name",name,"cells",List.copyOf(cells),"image",Objects.toString(raw.getOrDefault("poster",raw.getOrDefault("image","")),"")));
        }
        Map<String,Object> model=new LinkedHashMap<>(new AdminPage<>(matches,total,current,current>0,total>(current+1L)*AdminPage.SIZE).model());model.put("columns",columns(key));return model;
    }
    private Map<String,Class<? extends Row>> referenceTypes(){return Map.of("movieId",Movie.class,"cinemaId",Cinema.class,"roomId",Room.class,"genreId",Genre.class,"personId",Person.class,"userId",User.class);}
    private Map<String,Map<Long,String>> references(List<? extends Row> records){Map<String,Map<Long,String>> maps=new HashMap<>();for(var ref:referenceTypes().entrySet()){Map<Long,String> map=new HashMap<>();Set<Long> ids=new HashSet<>();for(Row row:records){Object value=db.view(row).get(ref.getKey());if(value instanceof Long id)ids.add(id);}if(!ids.isEmpty()){if(ref.getValue()==Room.class){db.query("select r.id,r.name,c.name from %s r, %s c where r.cinemaId=c.id and r.id in ?1".formatted(db.entityName(Room.class),db.entityName(Cinema.class)),Object[].class,ids).forEach(row->map.put((Long)row[0],row[2]+" · "+row[1]));}else for(Row row:db.list(ref.getValue(),"where e.id in ?1",ids)){var view=db.view(row);map.put(row.id,Objects.toString(view.getOrDefault("title",view.getOrDefault("name","#"+row.id))));}}maps.put(ref.getKey(),map);}return maps;}
    private Object format(String name,Object value,Map<String,Map<Long,String>> refs){if(value==null)return "—";if(refs.containsKey(name))return refs.get(name).getOrDefault(value,"#"+value);if(value instanceof Instant instant)return db.date(instant);if(value instanceof Boolean b)return b?"Có":"Không";if(Set.of("amount","price","minimum","maximum","surcharge").contains(name))return db.money(((Number)value).longValue());if(Set.of("fromMinute","toMinute").contains(name))return time(((Number)value).intValue());return text(value);}
    public static String time(int minute){return String.format("%02d:%02d",minute/60,minute%60);}
    public static Map<String,String> normalize(Map<String,String> values){Map<String,String> normalized=new HashMap<>(values);for(String name:List.of("fromMinute","toMinute")){String v=values.get(name);if(v!=null&&v.contains(":")){if(!v.matches("(?:[01][0-9]|2[0-3]):[0-5][0-9]")&&!(name.equals("toMinute")&&v.equals("24:00")))throw new AdminFormProblem("Giờ phải có dạng HH:mm; kết thúc ngày có thể là 24:00.",name);String[] parts=v.split(":");normalized.put(name,Integer.toString(Integer.parseInt(parts[0])*60+Integer.parseInt(parts[1])));}}return normalized;}
    public List<Map<String,Object>> groups(String key,Long id,Map<String,String> submitted){
        var resource=admin.resource(key);Row row;try{row=id==null?resource.type().getConstructor().newInstance():db.get(resource.type(),id);}catch(ReflectiveOperationException e){throw new IllegalStateException(e);}
        LinkedHashMap<String,List<Map<String,Object>>> groups=new LinkedHashMap<>();boolean protectedShow=key.equals("showtimes")&&id!=null&&admin.busyShow(id);
        for(String name:resource.fields().split(",")){try{Field field=resource.type().getField(name);Object raw=field.get(row);String value=submitted==null?raw instanceof Instant t?t.atZone(ReportService.ZONE).toLocalDateTime().toString():Objects.toString(raw,""):submitted.getOrDefault(name,"");if(submitted==null&&Set.of("fromMinute","toMinute").contains(name))value=time(((Number)raw).intValue());
            String type=field.getType()==boolean.class?"checkbox":field.getType()==Instant.class?"datetime-local":field.getType()==LocalDate.class?"date":Set.of("fromMinute","toMinute").contains(name)?"text":field.getType()==long.class||field.getType()==int.class?"number":Set.of("body","description","biography").contains(name)?"textarea":name.equals("email")?"email":"text";
            String group=Set.of("poster","banner","trailer","image").contains(name)?"Hình ảnh & truyền thông":Set.of("status","active","enabled","featured","visible","role").contains(name)?"Trạng thái & quyền":Set.of("amount","price","surcharge","fromMinute","toMinute","dayType","seatType","startsAt","endsAt","value","minimum","maximum","quota","perUser").contains(name)?"Lịch & giá trị":"Thông tin";
            if(key.equals("movies"))group=Set.of("poster","banner").contains(name)?"Poster / Banner":Set.of("trailer","featured","active","status").contains(name)?"Trailer và hiển thị":"Thông tin phim";boolean locked=protectedShow&&Set.of("movieId","roomId","startsAt","status").contains(name);if(locked)value=raw instanceof Instant t?t.atZone(ReportService.ZONE).toLocalDateTime().toString():Objects.toString(raw,"");Map<String,Object> item=new LinkedHashMap<>();item.put("name",name);item.put("label",label(name));item.put("value",value);item.put("locked",locked);item.put("type",type);item.put("checked",submitted==null?Boolean.TRUE.equals(raw):value.equals("true"));item.put("options",key.equals("movies")&&name.equals("status")?List.of(Map.of("value",value.equals("STOPPED")?"COMING_SOON":value,"label","Tự động theo ngày khởi chiếu"),Map.of("value","STOPPED","label","Ngừng chiếu")):options(key,name));if(row instanceof Movie movie&&name.equals("status")){item.put("lifecycle",MovieLifecycle.label(MovieLifecycle.status(movie,MovieLifecycle.today(clock))));item.put("movieToday",MovieLifecycle.today(clock).toString());item.put("missingDate",movie.releaseDate==null);}item.put("media",Set.of("poster","banner","trailer","image").contains(name));item.put("money",Set.of("amount","price","surcharge","minimum","maximum").contains(name));groups.computeIfAbsent(group,g->new ArrayList<>()).add(item);
        }catch(ReflectiveOperationException e){throw new IllegalStateException(e);}}
        return groups.entrySet().stream().map(e->Map.<String,Object>of("label",e.getKey(),"fields",e.getValue())).toList();
    }
    public List<Map<String,Object>> options(String key,String name){
        Class<? extends Row> ref=switch(name){case "movieId"->Movie.class;case "cinemaId"->Cinema.class;case "roomId"->Room.class;case "genreId"->Genre.class;case "personId"->Person.class;default->null;};
        if(ref!=null){Map<Long,String> cinemas=new HashMap<>();if(ref==Room.class)db.list(Cinema.class,"").forEach(c->cinemas.put(c.id,c.name));return db.list(ref,"order by e.id").stream().map(row->{var view=db.view(row);return Map.<String,Object>of("value",row.id.toString(),"label",Objects.toString(view.getOrDefault("title",view.getOrDefault("name","")))+(row instanceof Room r?" · "+cinemas.get(r.cinemaId):"")+" · #"+row.id);}).toList();}
        String[] choices=switch(name){case "role"->new String[]{"CUSTOMER","STAFF","ADMIN"};case "ageRating"->new String[]{"P","K","T13","T16","T18"};case "seatType","type"->new String[]{"STANDARD","VIP","COUPLE"};case "dayType"->new String[]{"WEEKDAY","WEEKEND"};case "status"->key.equals("movies")?new String[]{"COMING_SOON","NOW_SHOWING","STOPPED"}:new String[]{"DRAFT","OPEN","CANCELLED"};case "kind"->switch(key){case "credits"->new String[]{"ACTOR","DIRECTOR"};case "products"->new String[]{"FOOD","DRINK","COMBO"};case "vouchers"->new String[]{"FIXED","PERCENT"};default->new String[]{"BANNER","ARTICLE","OFFER","POLICY","ABOUT","CONTACT","NOTICE"};};default->new String[0];};return Arrays.stream(choices).map(v->Map.<String,Object>of("value",v,"label",text(v))).toList();
    }
    private String stateField(String key){return switch(key){case "movies","showtimes"->"status";case "users"->"role";case "credits","products","contents","vouchers"->"kind";case "prices"->"seatType";case "seats"->"type";case "genres","people","cinemas","rooms"->"active";case "reviews"->"visible";default->"";};}
    public List<Map<String,Object>> states(String key){String field=stateField(key);return field.isEmpty()?List.of():Set.of("active","visible").contains(field)?List.of(Map.of("value","true","label","Đang hoạt động / hiển thị"),Map.of("value","false","label","Đã ngừng / ẩn")):options(key,field);}
}
